Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB0LD_0RC1RD_1LD1RC_0LA1LA : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB0LD_0RC1RD_1LD1RC_0LA1LA : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S0] [] 0 0 []).
Definition chn_0RB0LD_0RC1RD_1LD1RC_0LA1LA : list lstep := [SWinR 4; SCycL 2 0; SWin 4; SCycR 2; SWin 4].

Lemma run_inner_0RB0LD_0RC1RD_1LD1RC_0LA1LA : srun tm false true chn_0RB0LD_0RC1RD_1LD1RC_0LA1LA AI0_0RB0LD_0RC1RD_1LD1RC_0LA1LA = Some (AI1_0RB0LD_0RC1RD_1LD1RC_0LA1LA, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB0LD_0RC1RD_1LD1RC_0LA1LA : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S0] [] 0 0 []).
Definition chb_0RB0LD_0RC1RD_1LD1RC_0LA1LA : list lstep := [SRotL 1; SWin 1; SRotL 1; SWin 3; SWinR 8; SCycL 2 0; SWin 2; SCycR 2; SWin 5; SUnrotL 1].

Lemma run_boot_0RB0LD_0RC1RD_1LD1RC_0LA1LA : srun tm true true chb_0RB0LD_0RC1RD_1LD1RC_0LA1LA B0_0RB0LD_0RC1RD_1LD1RC_0LA1LA = Some (BB1_0RB0LD_0RC1RD_1LD1RC_0LA1LA, 4, 19).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LD_0RC1RD_1LD1RC_0LA1LA : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB0LD_0RC1RD_1LD1RC_0LA1LA : list lstep := [SWinR 4; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_0RB0LD_0RC1RD_1LD1RC_0LA1LA : srun tm true true che_0RB0LD_0RC1RD_1LD1RC_0LA1LA BE0_0RB0LD_0RC1RD_1LD1RC_0LA1LA = Some (B1_0RB0LD_0RC1RD_1LD1RC_0LA1LA, 4, 11).
