(** ** The lap *)

Lemma lap_0RB0LD_1LA0RC_1RB____0LA___ : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LD_1LA0RC_1RB____0LA___ p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LD_1LA0RC_1RB____0LA___ B0_0RB0LD_1LA0RC_1RB____0LA___ B1_0RB0LD_1LA0RC_1RB____0LA___ 4 6 p j' [] []).
    + exact run_ovf_0RB0LD_1LA0RC_1RB____0LA___.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LD_1LA0RC_1RB____0LA___ p j' E).
    + exact (geo_0RB0LD_1LA0RC_1RB____0LA___ p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LD_1LA0RC_1RB____0LA___ : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 2.
  assert (H : match csteps tm 2 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 2 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

