  - exists (4 * j + 4), (cden [] [] j BB1_0RB0LD_1LA1RC_1LD1RB____1LA). split;
      [| exact (gbo_0RB0LD_1LA1RC_1LD1RB____1LA j)].
    rewrite (gso_0RB0LD_1LA1RC_1LD1RB____1LA p j E).
    exact (srun_sound tm true true chb_0RB0LD_1LA1RC_1LD1RB____1LA B0_0RB0LD_1LA1RC_1LD1RB____1LA BB1_0RB0LD_1LA1RC_1LD1RB____1LA 4 4
             run_boot_0RB0LD_1LA1RC_1LD1RB____1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB0LD_1LA1RC_1LD1RB____1LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB0LD_1LA1RC_1LD1RB____1LA j)].
