    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LD_1LA1RC_1LD1RB____1LA (StB, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0LD_1LA1RC_1LD1RB____1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LD_1LA1RC_1LD1RB____1LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LD_1LA1RC_1LD1RB____1LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
