Lemma gz_0RB0LD_1LA1RC_1LD1RC_0RB1LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_0RB0LD_1LA1RC_1LD1RC_0RB1LA /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_0RB0LD_1LA1RC_1LD1RC_0RB1LA = Cc (Pos.succ p).
