Lemma lapi_0RB0LD_1LA1RC_1LD1RC_0RB1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
