Definition mk_0RB0LD_1LA1RC_1RD0LA_1RB0LC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB0LD_1LA1RC_1RD0LA_1RB0LC.

(** 0RB0LD_1LA1RC_1RD0LA_1RB0LC *)
(** 0RB0LD_1LA1RC_1RD0LA_1RB0LC -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LD_1LA1RC_1RD0LA_1RB0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S0 DL StA
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S0 DL StC end.

(** Its mirror 0LB0RD_1RA1LC_1LD0RA_1LB0RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LD_1LA1RC_1RD0LA_1RB0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DL StC
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S0 DR StA
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LD_1LA1RC_1RD0LA_1RB0LC : list Instr := [].
Definition tmw_0RB0LD_1LA1RC_1RD0LA_1RB0LC : TM := tm_wrap_trs tmm_0RB0LD_1LA1RC_1RD0LA_1RB0LC pins_0RB0LD_1LA1RC_1RD0LA_1RB0LC.
Local Notation tm := tmw_0RB0LD_1LA1RC_1RD0LA_1RB0LC.

Lemma mirror_ok_0RB0LD_1LA1RC_1RD0LA_1RB0LC : mirror_tm tm_0RB0LD_1LA1RC_1RD0LA_1RB0LC = tmm_0RB0LD_1LA1RC_1RD0LA_1RB0LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB0LD_1LA1RC_1RD0LA_1RB0LC (p : positive) : cconf := (StA, (Ap_Alph_000_100_1 p ++ [S0], S0, [])).
Local Notation Cc := Cc_0RB0LD_1LA1RC_1RD0LA_1RB0LC.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_0RB0LD_1LA1RC_1RD0LA_1RB0LC : sconf := mkC StA (mkS [S0;S0;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_0RB0LD_1LA1RC_1RD0LA_1RB0LC : sconf := mkC StA (mkS [S1;S0;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_0RB0LD_1LA1RC_1RD0LA_1RB0LC : list lstep := [SWin 2].

Lemma run_z_0RB0LD_1LA1RC_1RD0LA_1RB0LC : srun tm false true chz_0RB0LD_1LA1RC_1RD0LA_1RB0LC Z0_0RB0LD_1LA1RC_1RD0LA_1RB0LC = Some (Z1_0RB0LD_1LA1RC_1RD0LA_1RB0LC, 0, 2).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
