Definition P0_0RB0LD_1LA1RC_1RD0LA_1RB0LC : sconf := mkC StA (mkS [S1;S0;S0] [S1;S0;S0] 1 0 [S0;S0;S0]) S0 (mkS [] [] 0 0 []).
Definition P1_0RB0LD_1LA1RC_1RD0LA_1RB0LC : sconf := mkC StA (mkS [S0;S0;S0] [S0;S0;S0] 1 0 [S1;S0;S0]) S0 (mkS [] [] 0 0 []).
Definition chp_0RB0LD_1LA1RC_1RD0LA_1RB0LC : list lstep := [SWin 3; SCycL 3 0; SWin 2; SCycR 3; SWin 3].

Lemma run_p_0RB0LD_1LA1RC_1RD0LA_1RB0LC : srun tm false true chp_0RB0LD_1LA1RC_1RD0LA_1RB0LC P0_0RB0LD_1LA1RC_1RD0LA_1RB0LC = Some (P1_0RB0LD_1LA1RC_1RD0LA_1RB0LC, 6, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB0LD_1LA1RC_1RD0LA_1RB0LC : sconf := mkC StA (mkS [] [S1;S0;S0] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB0LD_1LA1RC_1RD0LA_1RB0LC : sconf := mkC StA (mkS [] [S0;S0;S0] 1 1 [S1]) S0 (mkS [] [] 0 0 []).
Definition cho_0RB0LD_1LA1RC_1RD0LA_1RB0LC : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 5; SCycR 3; SWin 1; SRotL 2; SFoldL 1].

Lemma run_ovf_0RB0LD_1LA1RC_1RD0LA_1RB0LC : srun tm true true cho_0RB0LD_1LA1RC_1RD0LA_1RB0LC B0_0RB0LD_1LA1RC_1RD0LA_1RB0LC = Some (B1_0RB0LD_1LA1RC_1RD0LA_1RB0LC, 6, 8).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB0LD_1LA1RC_1RD0LA_1RB0LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z0_0RB0LD_1LA1RC_1RD0LA_1RB0LC /\
  cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z1_0RB0LD_1LA1RC_1RD0LA_1RB0LC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_000_100_1.cview_some_Alph_000_100_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB0LD_1LA1RC_1RD0LA_1RB0LC, cden, Z0_0RB0LD_1LA1RC_1RD0LA_1RB0LC, Z1_0RB0LD_1LA1RC_1RD0LA_1RB0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB0LD_1LA1RC_1RD0LA_1RB0LC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] j P0_0RB0LD_1LA1RC_1RD0LA_1RB0LC /\
  cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] j P1_0RB0LD_1LA1RC_1RD0LA_1RB0LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_000_100_1.cview_some_Alph_000_100_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB0LD_1LA1RC_1RD0LA_1RB0LC, cden, P0_0RB0LD_1LA1RC_1RD0LA_1RB0LC, P1_0RB0LD_1LA1RC_1RD0LA_1RB0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LD_1LA1RC_1RD0LA_1RB0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB0LD_1LA1RC_1RD0LA_1RB0LC p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB0LD_1LA1RC_1RD0LA_1RB0LC Z0_0RB0LD_1LA1RC_1RD0LA_1RB0LC Z1_0RB0LD_1LA1RC_1RD0LA_1RB0LC 0 2
               run_z_0RB0LD_1LA1RC_1RD0LA_1RB0LC (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB0LD_1LA1RC_1RD0LA_1RB0LC p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB0LD_1LA1RC_1RD0LA_1RB0LC P0_0RB0LD_1LA1RC_1RD0LA_1RB0LC P1_0RB0LD_1LA1RC_1RD0LA_1RB0LC 6 8
               run_p_0RB0LD_1LA1RC_1RD0LA_1RB0LC (Ap_Alph_000_100_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_0RB0LD_1LA1RC_1RD0LA_1RB0LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0LD_1LA1RC_1RD0LA_1RB0LC.
Proof.
  intros p j E. destruct (Alph_000_100_1.cview_none_Alph_000_100_1 p j E) as (H1 & _).
  unfold Cc_0RB0LD_1LA1RC_1RD0LA_1RB0LC, cden, B0_0RB0LD_1LA1RC_1RD0LA_1RB0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0LD_1LA1RC_1RD0LA_1RB0LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LD_1LA1RC_1RD0LA_1RB0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LD_1LA1RC_1RD0LA_1RB0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_000_100_1.cview_none_Alph_000_100_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LD_1LA1RC_1RD0LA_1RB0LC
             = (StA, (rep [S0;S0;S0] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_0RB0LD_1LA1RC_1RD0LA_1RB0LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S0;S0;S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB0LD_1LA1RC_1RD0LA_1RB0LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB0LD_1LA1RC_1RD0LA_1RB0LC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_0RB0LD_1LA1RC_1RD0LA_1RB0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LD_1LA1RC_1RD0LA_1RB0LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LD_1LA1RC_1RD0LA_1RB0LC B0_0RB0LD_1LA1RC_1RD0LA_1RB0LC B1_0RB0LD_1LA1RC_1RD0LA_1RB0LC 6 8 p j' [] []).
    + exact run_ovf_0RB0LD_1LA1RC_1RD0LA_1RB0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LD_1LA1RC_1RD0LA_1RB0LC p j' E).
    + exact (geo_0RB0LD_1LA1RC_1RD0LA_1RB0LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LD_1LA1RC_1RD0LA_1RB0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 2.
  assert (H : match csteps tm 2 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 2 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LD_1LA1RC_1RD0LA_1RB0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LD_1LA1RC_1RD0LA_1RB0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LD_1LA1RC_1RD0LA_1RB0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LD_1LA1RC_1RD0LA_1RB0LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LD_1LA1RC_1RD0LA_1RB0LC : forall t, ~ In t pins_0RB0LD_1LA1RC_1RD0LA_1RB0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LD_1LA1RC_1RD0LA_1RB0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LD_1LA1RC_1RD0LA_1RB0LC
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LD_1LA1RC_1RD0LA_1RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0LD_1LA1RC_1RD0LA_1RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LD_1LA1RC_1RD0LA_1RB0LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LD_1LA1RC_1RD0LA_1RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LD_1LA1RC_1RD0LA_1RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 5]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LD_1LA1RC_1RD0LA_1RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB0LD_1LA1RC_1RD0LA_1RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 4]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_0RB0LD_1LA1RC_1RD0LA_1RB0LC : NeverQuasiHaltsTr tmm_0RB0LD_1LA1RC_1RD0LA_1RB0LC.
Proof.
  apply (glue_neverqhtr tmm_0RB0LD_1LA1RC_1RD0LA_1RB0LC pins_0RB0LD_1LA1RC_1RD0LA_1RB0LC Cc 1).
  - exact boot_0RB0LD_1LA1RC_1RD0LA_1RB0LC.
  - intros p _. apply lap_0RB0LD_1LA1RC_1RD0LA_1RB0LC.
  - intros t Ht p _. apply fire_0RB0LD_1LA1RC_1RD0LA_1RB0LC. exact Ht.
Qed.

Theorem nqhtr_0RB0LD_1LA1RC_1RD0LA_1RB0LC : NeverQuasiHaltsTr tm_0RB0LD_1LA1RC_1RD0LA_1RB0LC.
Proof. apply (neverqhtr_mirror tm_0RB0LD_1LA1RC_1RD0LA_1RB0LC). rewrite mirror_ok_0RB0LD_1LA1RC_1RD0LA_1RB0LC. exact nqhtrm_0RB0LD_1LA1RC_1RD0LA_1RB0LC. Qed.

Theorem nonhalt_0RB0LD_1LA1RC_1RD0LA_1RB0LC : NonHalt tm_0RB0LD_1LA1RC_1RD0LA_1RB0LC.
Proof. apply never_qh_tr_nonhalt, nqhtr_0RB0LD_1LA1RC_1RD0LA_1RB0LC. Qed.

End LAPT_0RB0LD_1LA1RC_1RD0LA_1RB0LC.

Module LAPT_0RB0LD_1LC0LA_1LD1RC_0RC1LA.
(** * LAPT_0RB0LD_1LC0LA_1LD1RC_0RC1LA: TRANSITION-LEVEL board for machine 0RB0LD_1LC0LA_1LD1RC_0RC1LA, boarded by CERTIFICATE.

    Auto-emitted by tools/counters/emit_lapcert.py (UNTRUSTED emitter; the Coq
    kernel re-runs the checker on every line below).  Left-growth binary
    counter under the Ap_Alph_10_11_11 digit alphabet (Alph_10_11_11.v), anchored at

      Cc p = (StC, (Ap_Alph_10_11_11 p ++ [S0], S0, []))

    The lap is DATA, not a proof script: each branch is a list of steps for
    [Checkers/LapDecider.v], run by the kernel through [vm_compute] and
    discharged by the single theorem [srun_sound].

      interior  (cview p = (j, Some q0)):  4*j+8 steps
      overflow  (cview p = (S j, None)):   4*j+13 steps

    The interior branch closes EXACTLY (which is what feeds
    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 198 anchors.
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
