    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LD_1LC0RB_1LD1RC_0RC1LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LD_1LC0RB_1LD1RC_0RC1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
