(** ** The lap *)

Lemma lap_0RB0LD_1LC1RB_0RB1LA_0LC1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
