  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LD_1LC1RB_0RB1LA_0LC1LA [SWin 1; SWinR 3; SCycL 2 0; SWin 6; SCycR 2; SWin 2] (StD, S0) ltac:(vm_compute; reflexivity)
