    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LD_1LC1RB_1LD1LA_1RC1LA B0_0RB0LD_1LC1RB_1LD1LA_1RC1LA B1_0RB0LD_1LC1RB_1LD1LA_1RC1LA 4 13 p j' [] []).
