(** ** The lap *)

Lemma lap_0RB0LD_1LC1RB_1LD1RC_0RB1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LD_1LC1RB_1LD1RC_0RB1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LD_1LC1RB_1LD1RC_0RB1LA B0_0RB0LD_1LC1RB_1LD1RC_0RB1LA B1_0RB0LD_1LC1RB_1LD1RC_0RB1LA 4 19 p j' [] []).
    + exact run_ovf_0RB0LD_1LC1RB_1LD1RC_0RB1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LD_1LC1RB_1LD1RC_0RB1LA p j' E).
    + exact (geo_0RB0LD_1LC1RB_1LD1RC_0RB1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LD_1LC1RB_1LD1RC_0RB1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 34.
  assert (H : match csteps tm 34 c0 with
