    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LD_1LC1RB_1LD1RC_0RB1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LD_1LC1RB_1LD1RC_0RB1LA = Some t ->
  forall p j, cview p = (S j, None) ->
