Lemma gz_0RB0LD_1LC1RB_1RB1LA_1RC1LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] 0 Z0_0RB0LD_1LC1RB_1RB1LA_1RC1LA /\
