  - destruct (gz_0RB0LD_1LC1RB_1RB1LA_1RC1LA p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB0LD_1LC1RB_1RB1LA_1RC1LA Z0_0RB0LD_1LC1RB_1RB1LA_1RC1LA Z1_0RB0LD_1LC1RB_1RB1LA_1RC1LA 0 4
               run_z_0RB0LD_1LC1RB_1RB1LA_1RC1LA (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB0LD_1LC1RB_1RB1LA_1RC1LA p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB0LD_1LC1RB_1RB1LA_1RC1LA P0_0RB0LD_1LC1RB_1RB1LA_1RC1LA P1_0RB0LD_1LC1RB_1RB1LA_1RC1LA 4 8
               run_p_0RB0LD_1LC1RB_1RB1LA_1RC1LA (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
