Lemma geo_0RB0LD_1LC1RB_1RB1LA_1RC1LA : forall p j, cview p = (S (S j), None) ->
  lift (cden [] [] j B1_0RB0LD_1LC1RB_1RB1LA_1RC1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p (S j) E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LD_1LC1RB_1RB1LA_1RC1LA
