    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_B0_0RB0LD_1LC1RB_1RB1LA_1RC1LA.
    + exact (fireo_0RB0LD_1LC1RB_1RB1LA_1RC1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 4] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* B1 *)
