  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S1 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LD_1LC1RB_1RD1LA_1RC1LA : list Instr := [].
Definition tmw_0RB0LD_1LC1RB_1RD1LA_1RC1LA : TM := tm_wrap_trs tmm_0RB0LD_1LC1RB_1RD1LA_1RC1LA pins_0RB0LD_1LC1RB_1RD1LA_1RC1LA.
