(** ** The lap *)

Lemma lap_0RB0LD_1LC1RD_0RD0LA_1LA1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
