(** ** Bootstrap *)

Lemma boot_0RB0LD_1LC1RD_0RD0LA_1LA1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 7.
  assert (H : match csteps tm 7 c0 with
