    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LD_1LC1RD_1RB1LC_0LC1RA [SWin 1; SWinR 3; SCycL 3 0; SWin 10; SCycR 5; SWin 2; SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
