Lemma geo_0RB0LD_1RC0RA_1LA1RB_0LC0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LD_1RC0RA_1LA1RB_0LC0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (BpCounter.cview_none_B p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LD_1RC0RA_1LA1RB_0LC0LD
             = (StA, (rep [S0;S0] (S j) ++ [S0;S1], S0, (([]) ++ [S0]) ++ [S0]))).
  { unfold cden, B1_0RB0LD_1RC0RA_1LA1RB_0LC0LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S0;S0] (S j) ++ [S0;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB0LD_1RC0RA_1LA1RB_0LC0LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_0RB0LD_1RC0RA_1LA1RB_0LC0LD. reflexivity.
