(** ** The lap *)

Lemma lap_0RB0LD_1RC0RA_1LA1RC_0LC0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
