  - destruct (lapi_0RB0LD_1RC0RA_1LA1RC_0LC0LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LD_1RC0RA_1LA1RC_0LC0LD B0_0RB0LD_1RC0RA_1LA1RC_0LC0LD B1_0RB0LD_1RC0RA_1LA1RC_0LC0LD 2 10 p j' [] []).
    + exact run_ovf_0RB0LD_1RC0RA_1LA1RC_0LC0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LD_1RC0RA_1LA1RC_0LC0LD p j' E).
    + exact (geo_0RB0LD_1RC0RA_1LA1RC_0LC0LD p j' E).
    + lia.
