(** ** Bootstrap *)

Lemma boot_0RB0LD_1RC0RA_1LA1RC_0LC0LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
