    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LD_1RC0RA_1LA1RC_0LC0LD [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LD_1RC0RA_1LA1RC_0LC0LD [SWin 1; SCycL 1 0; SWin 2; SRotR 1; SWin 1; SCycR 1; SWinR 4] (StB, S1) ltac:(vm_compute; reflexivity)
