Lemma lbl_0RB0LD_1RC0RB_1LA1RA_1LC0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LD_1RC0RB_1LA1RA_1LC0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LD_1RC0RB_1LA1RA_1LC0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_000_100_1.cview_none_Alph_000_100_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LD_1RC0RB_1LA1RA_1LC0LA
             = (StB, (rep [S0;S0;S0] (S j) ++ [S1], S0, ((([]) ++ [S0]) ++ [S0]) ++ [S0]))).
  { unfold cden, B1_0RB0LD_1RC0RB_1LA1RA_1LC0LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S0;S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB0LD_1RC0RB_1LA1RA_1LC0LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
