Lemma geo_0RB0LD_1RC0RB_1LA1RA_1LC0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LD_1RC0RB_1LA1RA_1LC0LD) = lift (Cc (Pos.succ p)).
