(** ** The lap *)

Lemma lap_0RB0LD_1RC0RB_1LA1RB_1LC0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
