  - destruct (lapi_0RB0LD_1RC0RB_1LA1RB_1LC0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LD_1RC0RB_1LA1RB_1LC0LA B0_0RB0LD_1RC0RB_1LA1RB_1LC0LA B1_0RB0LD_1RC0RB_1LA1RB_1LC0LA 4 12 p j' [] []).
    + exact run_ovf_0RB0LD_1RC0RB_1LA1RB_1LC0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LD_1RC0RB_1LA1RB_1LC0LA p j' E).
    + exact (geo_0RB0LD_1RC0RB_1LA1RB_1LC0LA p j' E).
    + lia.
