Lemma fire_0RB0LD_1RC0RB_1LA1RB_1LC0LA : forall t, ~ In t pins_0RB0LD_1RC0RB_1LA1RB_1LC0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
