Lemma lapi_0RB0LD_1RC0RB_1LA1RB_1LC0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB0LD_1RC0RB_1LA1RB_1LC0LD p q0 E) as (HA & HB).
    exists (0 * 0 + 8), (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_0RB0LD_1RC0RB_1LA1RB_1LC0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_0RB0LD_1RC0RB_1LA1RB_1LC0LD Z0_0RB0LD_1RC0RB_1LA1RB_1LC0LD Z1_0RB0LD_1RC0RB_1LA1RB_1LC0LD 0 8
             run_z_0RB0LD_1RC0RB_1LA1RB_1LC0LD (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_0RB0LD_1RC0RB_1LA1RB_1LC0LD p j' q0 E) as (HA & HB).
    exists (4 * j' + 12), (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j' P1_0RB0LD_1RC0RB_1LA1RB_1LC0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_0RB0LD_1RC0RB_1LA1RB_1LC0LD P0_0RB0LD_1RC0RB_1LA1RB_1LC0LD P1_0RB0LD_1RC0RB_1LA1RB_1LC0LD 4 12
             run_p_0RB0LD_1RC0RB_1LA1RB_1LC0LD (Ap_Alph_00_10_1 q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
