(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB0LD_1RC0RB_1LA1RC_1LC0LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_0RB0LD_1RC0RB_1LA1RC_1LC0LD /\
  lift (cden (Kp q0 ++ [S0]) [] 0 Z1_0RB0LD_1RC0RB_1LA1RC_1LC0LD) = lift (Cc (Pos.succ p)).
