    apply (lap_of_run tm Cc true true cho_0RB0LD_1RC0RC_1LD1RB_1LA1LA B0_0RB0LD_1RC0RC_1LD1RB_1LA1LA B1_0RB0LD_1RC0RC_1LD1RB_1LA1LA 4 8 p j' [] []).
