(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LD_1RC1LB_0LA0RC_1RB1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ip q0 ++ [S0]) [] j A0_0RB0LD_1RC1LB_0LA0RC_1RB1LA.
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (H1 & _).
  unfold Cc_0RB0LD_1RC1LB_0LA0RC_1RB1LA, cden, A0_0RB0LD_1RC1LB_0LA0RC_1RB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_0RB0LD_1RC1LB_0LA0RC_1RB1LA : forall p j q0, cview p = (j, Some q0) ->
  cden (Ip q0 ++ [S0]) [] j A1_0RB0LD_1RC1LB_0LA0RC_1RB1LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (_ & H2).
  unfold Cc_0RB0LD_1RC1LB_0LA0RC_1RB1LA, cden, A1_0RB0LD_1RC1LB_0LA0RC_1RB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LD_1RC1LB_0LA0RC_1RB1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (6 * j + 4). split; [lia|].
  rewrite (gsi_0RB0LD_1RC1LB_0LA0RC_1RB1LA p j q0 E).
  rewrite (srun_sound tm false true chi_0RB0LD_1RC1LB_0LA0RC_1RB1LA A0_0RB0LD_1RC1LB_0LA0RC_1RB1LA A1_0RB0LD_1RC1LB_0LA0RC_1RB1LA 6 4
             run_int_0RB0LD_1RC1LB_0LA0RC_1RB1LA (Ip q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_0RB0LD_1RC1LB_0LA0RC_1RB1LA p j q0 E).
Qed.

Lemma gso_0RB0LD_1RC1LB_0LA0RC_1RB1LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0LD_1RC1LB_0LA0RC_1RB1LA.
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (H1 & _).
  unfold Cc_0RB0LD_1RC1LB_0LA0RC_1RB1LA, cden, B0_0RB0LD_1RC1LB_0LA0RC_1RB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0LD_1RC1LB_0LA0RC_1RB1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LD_1RC1LB_0LA0RC_1RB1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LD_1RC1LB_0LA0RC_1RB1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LD_1RC1LB_0LA0RC_1RB1LA
             = (StC, (rep [S1;S0] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_0RB0LD_1RC1LB_0LA0RC_1RB1LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB0LD_1RC1LB_0LA0RC_1RB1LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB0LD_1RC1LB_0LA0RC_1RB1LA. reflexivity.
Qed.

Lemma gsn_0RB0LD_1RC1LB_0LA0RC_1RB1LA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_0RB0LD_1RC1LB_0LA0RC_1RB1LA.
