Lemma gen_0RB0LD_1RC1LB_0LA0RC_1RB1LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LD_1RC1LB_0LA0RC_1RB1LA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB0LD_1RC1LB_0LA0RC_1RB1LA, cden, AI1_0RB0LD_1RC1LB_0LA0RC_1RB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
